#!/usr/bin/env bash
# ============================================================
# apply_fixed_tb.sh
#
# Overwrites agents/, env/, test/ and seq_lib/ in your AXI
# mixed-protocol UVM testbench with the fixed versions from
# this session (see docs/BUG_ANALYSIS.md and docs/CHANGE_GUIDE.md
# for what changed and why).
#
# SAFE BY DEFAULT:
#   - Every file this script is about to overwrite is backed up
#     first into ./tb_backup_<timestamp>/<same relative path>,
#     but ONLY if it already exists and its content differs.
#   - Nothing outside agents/, env/, test/, seq_lib/ is touched.
#     (interfaces/, scoreboard/, coverage/, top/, sim/, docs/ are
#     NOT included here -- ask if you want those too.)
#
# USAGE:
#   cd <your project root>        # the dir containing agents/, env/, ...
#   bash apply_fixed_tb.sh          # apply, with backup
#   bash apply_fixed_tb.sh --dry-run   # show what would change, touch nothing
#
# Run this from the root of YOUR project tree (the directory that
# directly contains agents/, env/, test/, seq_lib/), not from
# inside any of those folders.
# ============================================================
set -euo pipefail

DRY_RUN=0
if [[ "${1:-}" == "--dry-run" ]]; then
    DRY_RUN=1
    echo "[dry-run] No files will be written."
fi

if [[ ! -d agents || ! -d seq_lib ]]; then
    echo "ERROR: run this from your project root (agents/ and seq_lib/ not found here)." >&2
    exit 1
fi

TS=$(date +%Y%m%d_%H%M%S)
BACKUP_DIR="tb_backup_${TS}"
CHANGED=0
UNCHANGED=0
NEW=0

write_file() {
    local relpath="$1"
    local b64="$2"
    local dest="$relpath"
    local tmp
    tmp=$(mktemp)
    echo "$b64" | base64 -d > "$tmp"

    if [[ -f "$dest" ]]; then
        if cmp -s "$tmp" "$dest"; then
            UNCHANGED=$((UNCHANGED+1))
            rm -f "$tmp"
            return
        fi
        CHANGED=$((CHANGED+1))
        if [[ $DRY_RUN -eq 1 ]]; then
            echo "  would update: $dest"
            rm -f "$tmp"
            return
        fi
        mkdir -p "$(dirname "${BACKUP_DIR}/${dest}")"
        cp "$dest" "${BACKUP_DIR}/${dest}"
        echo "  updated (backed up): $dest"
    else
        NEW=$((NEW+1))
        if [[ $DRY_RUN -eq 1 ]]; then
            echo "  would create: $dest"
            rm -f "$tmp"
            return
        fi
        echo "  created: $dest"
    fi

    mkdir -p "$(dirname "$dest")"
    mv "$tmp" "$dest"
}

echo "Applying fixed testbench files (agents/, env/, test/, seq_lib/)..."
echo

